property.value:
let $chain := function($node) {
      $node/ancestor::MethodCall[let $call := . return
        not($node/ancestor-or-self::*[exists(ancestor::*[. is $call])][preceding-sibling::*])]
    },
    $stored := function($node) {
      string(($node/parent::VariableDeclarator/VariableId/@Name,
              $node/parent::CastExpression/parent::VariableDeclarator/VariableId/@Name,
              $node/parent::AssignmentExpression/*[1]/@Name,
              $node/parent::CastExpression/parent::AssignmentExpression/*[1]/@Name)[1])
    },
    $scope := function($node) {
      ($node/ancestor::*[self::MethodDeclaration or self::ConstructorDeclaration or self::Initializer
                         or self::LambdaExpression][1], $node/ancestor::ClassBody[last()])[1]
    },
    $initializers := function($node, $names) {
      ($scope($node)//VariableDeclarator[VariableId/@Name = $names]/*[2],
       $node/ancestor::ClassBody[last()]/FieldDeclaration/VariableDeclarator[VariableId/@Name = $names]/*[2])
    },
    $http := function($call) {
      let $first := $initializers($call, $call/*[1]/descendant-or-self::VariableAccess/@Name),
          $second := $initializers($call, $first/descendant-or-self::VariableAccess/@Name)
      return exists(($call/*[1], $first, $second)/descendant-or-self::StringLiteral[matches(@ConstValue, '^https?://', 'i')])
    },
    $unset := function($node, $setters) {
      let $chained := $chain($node)
      return if ($chained[@MethodName = $setters]) then false()
        else if ($chained[@MethodName = 'build']) then true()
        else let $name := $stored($node) return $name != ''
          and not($scope($node)//MethodCall[@MethodName = $setters][.//VariableAccess[@Name = $name]])
    }
return (
  //MethodCall[@MethodName = 'newHttpClient'][*[1][self::TypeExpression][pmd-java:typeIs('java.net.http.HttpClient')]]
  | //MethodCall[@MethodName = 'newBuilder'][*[1][self::TypeExpression][pmd-java:typeIs('java.net.http.HttpClient')]]
      [$unset(., 'connectTimeout')]
  | //MethodCall[@MethodName = 'newBuilder'][*[1][self::TypeExpression][pmd-java:typeIs('java.net.http.HttpRequest')]]
      [$unset(., 'timeout')]
  | //MethodCall[@MethodName = 'openConnection'][*[1][pmd-java:typeIs('java.net.URL')]]
      [parent::CastExpression[pmd-java:typeIs('java.net.HttpURLConnection')]
       or parent::VariableDeclarator/parent::LocalVariableDeclaration[pmd-java:typeIs('java.net.HttpURLConnection')]
       or $http(.)]
      [let $name := $stored(.) return
        if ($name != '')
        then not($scope(.)//MethodCall[@MethodName = 'setConnectTimeout'][.//VariableAccess[@Name = $name]]
                 and $scope(.)//MethodCall[@MethodName = 'setReadTimeout'][.//VariableAccess[@Name = $name]])
        else exists(parent::MethodCall | parent::CastExpression/parent::MethodCall)]
  | //MethodCall[@MethodName = 'openStream'][*[1][pmd-java:typeIs('java.net.URL')]][$http(.)]
  | //MethodCall[@MethodName = ('createDefault', 'createSystem', 'createMinimal')]
      [*[1][self::TypeExpression][pmd-java:typeIs('org.apache.http.impl.client.HttpClients')
        or pmd-java:typeIs('org.apache.hc.client5.http.impl.classic.HttpClients')]]
  | //MethodCall[@MethodName = 'custom']
      [*[1][self::TypeExpression][pmd-java:typeIs('org.apache.http.impl.client.HttpClients')
        or pmd-java:typeIs('org.apache.hc.client5.http.impl.classic.HttpClients')]]
      [$unset(., ('setDefaultRequestConfig', 'setConnectionManager', 'setDefaultSocketConfig'))]
)
